    ctx.gpr[2] = call_guest(rt, ctx, 0x08955358u, {object, frame.at(0u)});
    const float x = float_at(rt, frame.at(0u)), y = float_at(rt, frame.at(4u)), z = float_at(rt, frame.at(8u));
    const float sum = psp_mul(x, x) + psp_mul(y, y) + psp_mul(z, z);
