            const std::uint32_t next = word(rt, node + 0x8u);
            (void)call_guest(rt, ctx, kUnlock, {self + 0xCu});
            (void)call_guest(rt, ctx, fn, {value});
            (void)call_guest(rt, ctx, kLock, {self + 0xCu});
