        rt.memory().store32(self + 44u + 4u * (first + j), std::bit_cast<std::uint32_t>(psp_mul(byte_float(curve + 20u + j), x)));
        rt.memory().store32(self + 76u + 4u * (first + j), std::bit_cast<std::uint32_t>(psp_mul(byte_float(curve + 24u + j), z)));
