        store_float(rt, car + 1408u, call_guest(rt, ctx, 0x0894BFA0u, {body, car + 1232u}, {float_at(rt, car + 1424u)}).f0);
        const float base = float_at(rt, car + 1696u) + float_at(rt, car + 1668u);
        float sum = 0.0f;
