    const auto last = static_cast<std::uint32_t>(signed_half(rt, curve) - 1);
    const auto key = [&](std::uint32_t i) { return float_at(rt, keys + i * 4u); };
    const auto value = [&](std::uint32_t i) { return float_at(rt, word(rt, curve + 8u) + i * 4u); };
