        (void)call_guest(rt, ctx, 0x08BEED1Cu, {frame.at(12u), separator, call_guest(rt, ctx, 0x08B35F60u, {separator})});
        (void)call_guest(rt, ctx, 0x08B855E0u, {out, frame.at(12u)});
