    (void)call_guest(rt, ctx, 0x08A69B3Cu, {key, name});
    (void)call_guest(rt, ctx, 0x08A7BFD0u, {self, handler, key});
    (void)call_guest(rt, ctx, 0x08A69D68u, {key});
