        (void)call_guest(rt, ctx, 0x08A76AA0u, {result});
        for (std::uint32_t k = 0u; k < arguments; ++k) (void)call_guest(rt, ctx, 0x08A76AA0u, {values + 4u * k});
        rt.memory().store32(ctx.gpr[29], x);
